import { isSolutionId } from '@/lib/solutions/model';
import { consentVersion, readContact, type ContactDetails } from './model';

/**
 * A proposal to several projects at once (SHCWS-62): one form, the same data for each,
 * one ordinary contact request per project. Everything here is pure so the rules can be
 * tested without a database; db/contact-batches.sql and batch-server.ts do the writing.
 */
export const batchMaxRecipients = 3;

export type BatchRecipient = {
  /** The request's own id, generated by the browser once, so a retry never duplicates it. */
  id: string;
  solutionId: string;
  /**
   * The account the buyer was shown as the recipient; the server checks it still is.
   * Empty for a project the buyer had already written to: nothing is sent to it.
   */
  recipientId: string;
  /**
   * The buyer authorised sharing this request with this recipient. False only for a
   * project the buyer had already written to: it joins the group, nothing new is sent.
   */
  consent: boolean;
};

export type BatchInput = {
  id: string;
  /**
   * The buyer's list the projects were chosen from, or null for a temporary comparison
   * from the catalog (SHCWS-53): then nothing ties them together but this grouping.
   */
  listId: string | null;
  details: ContactDetails;
  recipients: BatchRecipient[];
};

function readRecipient(value: unknown): BatchRecipient | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const item = value as Record<string, unknown>;
  if (
    typeof item.id !== 'string' ||
    !isSolutionId(item.id) ||
    typeof item.solutionId !== 'string' ||
    !isSolutionId(item.solutionId) ||
    typeof item.consent !== 'boolean'
  )
    return null;
  // A request that will be created names the recipient the buyer consented to.
  const recipientId =
    typeof item.recipientId === 'string' && isSolutionId(item.recipientId) ? item.recipientId : '';
  if (item.consent && !recipientId) return null;
  return { id: item.id, solutionId: item.solutionId, recipientId, consent: item.consent };
}

/**
 * The body of POST /api/contacts/batch, or null when anything is missing or out of
 * bounds. The contact data is read with the single request's own validator, so a batch
 * accepts exactly what one request accepts; identity and routing come from the session
 * and the server, never from these fields.
 */
export function readBatch(body: Record<string, unknown>): BatchInput | null {
  const details = readContact(body);
  if (
    !details ||
    typeof body.id !== 'string' ||
    !isSolutionId(body.id) ||
    (body.listId !== undefined &&
      body.listId !== null &&
      (typeof body.listId !== 'string' || !isSolutionId(body.listId))) ||
    body.consentVersion !== consentVersion ||
    !Array.isArray(body.recipients) ||
    body.recipients.length < 1 ||
    body.recipients.length > batchMaxRecipients
  )
    return null;
  const recipients = body.recipients.map(readRecipient);
  if (recipients.some(item => item === null)) return null;
  const valid = recipients as BatchRecipient[];
  const solutions = new Set(valid.map(item => item.solutionId));
  const ids = new Set(valid.map(item => item.id));
  if (
    solutions.size !== valid.length ||
    ids.size !== valid.length ||
    ids.has(body.id) ||
    !valid.some(item => item.consent)
  )
    return null;
  const listId = typeof body.listId === 'string' ? body.listId : null;
  return { id: body.id, listId, details, recipients: valid };
}

/** What the server does for each recipient before writing anything. */
export type BatchStep = {
  recipient: BatchRecipient;
  /** Its position in the buyer's selection (0–2). */
  position: number;
  /**
   * create: a new request with the buyer's consent.
   * retry: this batch already created it on an earlier attempt (same request id).
   * existing: the buyer had written to this project before; nothing new is sent.
   */
  action: 'create' | 'retry' | 'existing';
  /** The request already on file for this project, if any. */
  requestId?: string;
};

/**
 * Plans a batch against the requests the buyer already has, keyed by solution id
 * (§9: one request per buyer and project). Returns null when a project would get a new
 * request without the buyer's consent for it: then nothing is written at all.
 */
export function planBatch(
  recipients: readonly BatchRecipient[],
  existing: ReadonlyMap<string, string>,
): BatchStep[] | null {
  const steps: BatchStep[] = [];
  for (const [position, recipient] of recipients.entries()) {
    const requestId = existing.get(recipient.solutionId);
    if (requestId === recipient.id) steps.push({ recipient, position, action: 'retry', requestId });
    else if (requestId) steps.push({ recipient, position, action: 'existing', requestId });
    else if (recipient.consent && recipient.recipientId)
      steps.push({ recipient, position, action: 'create' });
    else return null;
  }
  return steps;
}

/**
 * The single create returns the request on file for that buyer and project. If it is not
 * the id this batch generated, another tab got there first: the buyer had already written.
 */
export function createdOutcome(sentId: string, returnedId: string): 'sent' | 'existing' {
  return sentId === returnedId ? 'sent' : 'existing';
}

/**
 * The need as each project receives it: what the buyer wrote, then the questions they
 * asked everyone to answer, so the answers can be compared. The buyer reviews this exact
 * text before sending.
 */
export function composeNeed(need: string, questions: readonly string[], heading: string) {
  const text = need.trim();
  const asked = questions.map(question => question.trim()).filter(Boolean);
  if (!asked.length) return text;
  return `${text}\n\n${heading}\n${asked.map(question => `• ${question}`).join('\n')}`;
}
